function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function makeUUID(){return crypto.randomUUID?crypto.randomUUID():'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.random()*16|0;return(c==='x'?r:(r&3|8)).toString(16)})}
function merchantCreationKey(){let key=sessionStorage.getItem('barrioMerchantCreationKey');if(!key){key=makeUUID();sessionStorage.setItem('barrioMerchantCreationKey',key)}return key}
function showToast(msg){toastEl.textContent=msg;toastEl.classList.add('show');clearTimeout(showToast.t);showToast.t=setTimeout(()=>toastEl.classList.remove('show'),2400)}
function business(name){return businesses.find(b=>b.merchantId===name||b.id===name||b.name===name)||businesses[0]||{name:'Comercio local',kind:'Todos',type:'Comercio local',zone:'',emoji:'🏪',art:'cafe',about:'',followers:'—',posts:'—'}}
function setPage(page){state.page=page;state.chat=null;render();if(['home','map','business','shop-discover','storefront'].includes(page))void refreshBusinessDirectory();if(['merchant-dashboard','merchant-orders','merchant-order-detail'].includes(page))void refreshMerchantOrders();if(page==='my-orders')void refreshBuyerOrders()}
function openBusiness(name){state.selectedBusiness=name;state.page='business';render();void refreshBusinessDirectory()}
function navGlyph(id){const paths={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',map:'<path d="m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3z"/><path d="M9 3v15m6-12v15"/>',messages:'<path d="M4 5.5A3.5 3.5 0 0 1 7.5 2h9A3.5 3.5 0 0 1 20 5.5v8a3.5 3.5 0 0 1-3.5 3.5H10l-5 4v-5.2A3.5 3.5 0 0 1 4 13.5z"/><path d="M8 8h8m-8 4h6"/>',profile:'<circle cx="12" cy="7" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>'};return `<svg class="nav-svg" viewBox="0 0 24 24" aria-hidden="true">${paths[id]||''}</svg>`}
function navRender(){if(['onboarding','login'].includes(state.page)){nav.innerHTML='';return}const owner=state.page.startsWith('merchant-');if(owner){const items=[['merchant-dashboard','⌂','Inicio'],['merchant-products','▣','Productos'],['merchant-orders','▤','Pedidos'],['merchant-analytics','▥','Ventas'],['merchant-more','···','Más']];nav.innerHTML=items.map(([id,icon,label])=>`<button class="nav-item ${state.page===id||state.page==='merchant-product-form'&&id==='merchant-products'||state.page==='merchant-order-detail'&&id==='merchant-orders'||(state.page==='merchant-payment-settings'||state.page==='merchant-businesses')&&id==='merchant-more'?'active':''}" data-owner-page="${id}"><span class="owner-nav-icon">${icon}</span><span>${label}</span></button>`).join('');return}nav.innerHTML=navItems.map(([id,label])=>`<button class="nav-item ${state.page===id||state.page==='business'&&id==='map'||state.page==='chat'&&id==='messages'||state.page==='marketing'&&id==='profile'||['shop-discover','storefront','product-detail','cart','checkout','payment-processing','order-confirmation','my-orders','customer-order-detail'].includes(state.page)&&id==='home'?'active':''}" data-page="${id}" aria-label="${label}">${id==='compose'?`<span class="nav-create">＋</span>`:`${navGlyph(id)}${id==='messages'?'<span class="nav-badge">3</span>':''}`}<span>${label}</span></button>`).join('')}
function header(title,sub='',action=''){return `<div class="page-header"><div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${action}</div>`}
function searchBox(value,placeholder,action='search-change',klass=''){return `<label class="search ${klass}"><span>⌕</span><input data-action="${action}" value="${esc(value)}" placeholder="${placeholder}" aria-label="${placeholder}" /></label>`}
function photoClass(b){return {'Café Nopal':'photo-cafe','Florería El Jardín':'photo-florist','Taller Luna':'photo-workshop','Panadería La Espiga':'photo-feed'}[b.name]||'photo-cafe'}
function artCard(b){return `<article class="business-card" data-open-business="${esc(b.merchantId||b.id||b.name)}"><div class="business-art ${esc(b.art||'cafe')} ${photoClass(b)}"><span class="art-emoji">${esc(b.emoji||'🏪')}</span></div><div class="business-info"><strong>${esc(b.name)}</strong><small>${esc(b.type)}</small><div class="business-loc">⌖ ${esc(b.zone)}<span style="margin-left:auto;color:#258a41;font-size:17px">＋</span></div></div></article>`}
function avatar(emoji,extra=''){return `<div class="avatar ${extra}">${emoji}</div>`}
function postCard(post){return `<article class="post-card"><div class="post-author">${avatar(post.emoji||'☕')}<div><strong>${esc(post.name)}</strong><small>${esc(post.meta||'Hace 2 horas · Roma Norte')}</small></div><button class="more" data-toast="Más opciones próximamente">···</button></div><div class="post-text">${esc(post.text)}</div>${post.image?`<div class="post-image ${post.photo?'photo-feed':''}">${post.photo?'':`<span>${post.image}</span>`}</div>`:''}<div class="post-actions"><button class="post-action" data-toast="Te gusta esta publicación">♡ Me gusta</button><button class="post-action" data-toast="Comentarios próximamente">◯ Comentar</button><button class="post-action" data-toast="Enlace copiado">↗ Compartir</button></div></article>`}
