function syncMapPinsFromBusinesses(){const spots=[[20,26], [69,36], [49,50], [34,68], [74,76]];const colors=['','pink','blue','gold','green'];mapPins.splice(0,mapPins.length,...businesses.map((merchant,index)=>{const [x,y]=spots[index%spots.length];return {n:merchant.merchantId||merchant.id||merchant.name,x,y,e:merchant.emoji||'🏪',c:colors[index%colors.length]}}));const selected=businesses.find((merchant)=>merchant.merchantId===state.selectedBusiness||merchant.id===state.selectedBusiness||merchant.name===state.selectedBusiness);if(selected)state.selectedBusiness=selected.merchantId||selected.id||selected.name;else{state.selectedBusiness=businesses[0]?.merchantId||businesses[0]?.id||businesses[0]?.name||'';state.mapDetailOpen=false}}
let directoryRefreshPromise=null;
let directorySignature='';
async function refreshBusinessDirectory({rerender=true}={}){
 if(directoryRefreshPromise)return directoryRefreshPromise;
 directoryRefreshPromise=(async()=>{
  const response=await apiJson('/api/v1/merchants');
  const items=Array.isArray(response.items)?response.items:[];
  const next=items.map((merchant)=>({...merchant,followers:merchant.followers||'—',posts:merchant.posts||'—'}));
  const signature=JSON.stringify(next);
  if(signature!==directorySignature){
   businesses.splice(0,businesses.length,...next);
   directorySignature=signature;
   syncMapPinsFromBusinesses();
   if(rerender){const scrollTop=app.scrollTop;render();app.scrollTop=scrollTop}
  }
  return next;
 })();
 try{return await directoryRefreshPromise}
 catch(error){console.warn('No se pudo actualizar el directorio de comercios',error);return null}
 finally{directoryRefreshPromise=null}
}
